class DatabasePaginator:
    """
    A class to handle pagination of database queries.
    """

    def __init__(self, page_size=10, page_number=1):
        self.page_size = page_size
        self.page_number = page_number

    def get_paginated_data(self, query):
        """
        Returns paginated data based on the current page and page size.
        """
